<?php
declare(strict_types=1);
require_once __DIR__.'/../../app/config/database.php';require_once __DIR__.'/../../app/helpers/auth.php';require_once __DIR__.'/../../app/helpers/view.php';requireAdmin();$pdo=db();$status=$_GET['status']??'';if(!in_array($status,['','confirmed','cancelled'],true))$status='';
$sql="SELECT b.booking_id,b.status,b.total_amount,b.created_at,u.full_name,u.email,e.title,s.starts_at,v.name venue_name,p.payment_status,p.provider_reference,GROUP_CONCAT(CONCAT(seats.section_name,' ',seats.row_label,seats.seat_number) ORDER BY seats.section_name,seats.row_label,seats.seat_number SEPARATOR ', ') seat_labels FROM bookings b JOIN users u ON u.user_id=b.user_id JOIN shows s ON s.show_id=b.show_id JOIN events e ON e.event_id=s.event_id JOIN venues v ON v.venue_id=s.venue_id LEFT JOIN payments p ON p.booking_id=b.booking_id LEFT JOIN booking_seats bs ON bs.booking_id=b.booking_id LEFT JOIN show_seats ss ON ss.show_seat_id=bs.show_seat_id LEFT JOIN seats ON seats.seat_id=ss.seat_id";$params=[];if($status!==''){$sql.=' WHERE b.status=:status';$params['status']=$status;}$sql.=' GROUP BY b.booking_id,p.payment_id ORDER BY b.created_at DESC LIMIT 200';$st=$pdo->prepare($sql);$st->execute($params);$bookings=$st->fetchAll();$pageTitle='Booking overview';require_once __DIR__.'/../../app/includes/header.php';
?>
<section class="featured-events"><div class="section-heading"><p class="eyebrow"><a href="/admin/">ADMIN</a></p><h1>Booking overview</h1><p>Review recent bookings and payment references. Showing up to 200 most recent records.</p></div><p class="form-message">Cancellations and refunds are not available here until a refund policy is defined.</p><form class="event-search" method="get"><label for="status">Status</label><select id="status" name="status"><option value="">All bookings</option><option value="confirmed" <?=$status==='confirmed'?'selected':''?>>Confirmed</option><option value="cancelled" <?=$status==='cancelled'?'selected':''?>>Cancelled</option></select><button class="btn">Filter</button></form><div class="event-grid"><?php if(!$bookings):?><div class="empty-state"><h2>No bookings found</h2></div><?php endif;?><?php foreach($bookings as $b):?><article class="event-card"><div class="event-card-content"><span class="event-category"><?=e($b['status'])?> · <?=e($b['payment_status']??'no payment record')?></span><h2><?=e($b['title'])?></h2><p><?=e($b['full_name'])?> · <?=e($b['email'])?></p><p><?=e($b['venue_name'])?> · <?=e((new DateTimeImmutable($b['starts_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Kolkata'))->format('d M Y, g:i A'))?> IST</p><p>Seats: <?=e($b['seat_labels']??'—')?></p><p>Booking #<?=(int)$b['booking_id']?> · <?=e(formatIstDateTime($b['created_at'],'d M Y, g:i A'))?></p><?php if($b['provider_reference']):?><p>Payment reference: <?=e($b['provider_reference'])?></p><?php endif;?><strong>₹<?=e(number_format((float)$b['total_amount'],2))?></strong></div></article><?php endforeach;?></div></section><?php require_once __DIR__.'/../../app/includes/footer.php';?>
